"""Exact-to-the-penny order pricing (integer pennies, half-up rounding)."""

from dataclasses import dataclass
from decimal import MAX_EMAX, MAX_PREC, MIN_EMIN, Context, Decimal
from typing import List

from .parse import to_int

_EXACT = Context(prec=MAX_PREC, Emax=MAX_EMAX, Emin=MIN_EMIN)
TAX_PERCENT = {"standard": 20, "reduced": 5, "zero": 0}


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def pennies_to_decimal(pennies):
    """Exact Decimal with two places from integer pennies (no context rounding)."""
    return Decimal(pennies).scaleb(-2, context=_EXACT)


def _to_pennies(price):
    """A Decimal price in whole pennies (exact for two places; else half up)."""
    _, digits, exponent = price.as_tuple()
    number = to_int("".join(map(str, digits)) or "0")
    if exponent >= -2:
        return number * 10 ** (exponent + 2)
    scale = 10 ** (-exponent - 2)
    return (number * 2 + scale) // (2 * scale)


def _percent(amount, percent):
    """amount * percent / 100, rounded half up (non-negative amount)."""
    return (amount * percent * 2 + 100) // 200


def price_order(order, catalog) -> Quote:
    unit_pennies = []
    gross = []
    discount = []
    for sku, quantity in order.lines:
        price = catalog[sku].price
        cents = _to_pennies(price)
        line_gross = quantity * cents
        rate = 10 if quantity >= 50 else 5 if quantity >= 10 else 0
        unit_pennies.append(cents)
        gross.append(line_gross)
        discount.append(_percent(line_gross, rate))
    nets = [g - d for g, d in zip(gross, discount)]
    subtotal = sum(nets)
    order_discount = _percent(subtotal, 3) if subtotal >= 50000 else 0
    shares = [0] * len(nets)
    if order_discount:
        floors = [order_discount * n // subtotal for n in nets]
        remainders = [order_discount * n % subtotal for n in nets]
        leftover = order_discount - sum(floors)
        ranked = sorted(range(len(nets)), key=lambda i: (-remainders[i], i))
        shares = list(floors)
        for i in ranked[:leftover]:
            shares[i] += 1
    tax = 0
    for (sku, _), net, share in zip(order.lines, nets, shares):
        tax += _percent(net - share, TAX_PERCENT[catalog[sku].tax])
    lines = [
        QuoteLine(
            sku,
            quantity,
            pennies_to_decimal(unit),
            pennies_to_decimal(g),
            pennies_to_decimal(-d),
            pennies_to_decimal(n),
        )
        for (sku, quantity), unit, g, d, n in zip(order.lines, unit_pennies, gross, discount, nets)
    ]
    return Quote(
        lines,
        pennies_to_decimal(subtotal),
        pennies_to_decimal(-order_discount),
        pennies_to_decimal(tax),
        pennies_to_decimal(subtotal - order_discount + tax),
    )
"""The `stockroom` command line."""

import csv
import io
import json
import os
import re
import sys

from . import parse as P
from .pricing import price_order

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND ...\n"
    "  stock [--json] | low [--json] | history SKU [--json]\n"
    "  receive DATE SKU QUANTITY [NOTE] | ship DATE SKU QUANTITY [NOTE]\n"
    "  quote ORDER [--json] | fulfil ORDER DATE | invoice ORDER [--json]\n"
    "  report [--format text|csv|json]"
)
# command -> (min positionals, max positionals, options it accepts besides --dir)
COMMANDS = {
    "stock": (0, 0, ("--json",)),
    "low": (0, 0, ("--json",)),
    "history": (1, 1, ("--json",)),
    "receive": (3, 4, ()),
    "ship": (3, 4, ()),
    "fulfil": (2, 2, ()),
    "quote": (1, 1, ("--json",)),
    "invoice": (1, 1, ("--json",)),
    "report": (0, 0, ("--format",)),
}
RAW_COMMANDS = ("receive", "ship", "fulfil")


class Fail(Exception):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code
        self.message = message


def usage_error(message):
    return Fail(2, "%s\n%s" % (message, USAGE))


def parse_args(argv):
    """Return (command, directory, options dict, positionals); raise Fail(2)."""
    directory = "."
    command = None
    options = {}
    positionals = []
    args = list(argv)
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if arg == "--dir" or arg.startswith("--dir="):
            if arg == "--dir":
                if i >= len(args):
                    raise usage_error("option --dir needs a value")
                directory = args[i]
                i += 1
            else:
                directory = arg[len("--dir="):]
        elif command in RAW_COMMANDS or (command is not None and not arg.startswith("-")):
            positionals.append(arg)
        elif command is None and not arg.startswith("-"):
            if arg not in COMMANDS:
                raise usage_error("unknown command %r" % arg)
            command = arg
        elif arg == "--json":
            options["--json"] = True
        elif arg == "--format" or arg.startswith("--format="):
            if arg == "--format":
                if i >= len(args):
                    raise usage_error("option --format needs a value")
                options["--format"] = args[i]
                i += 1
            else:
                options["--format"] = arg[len("--format="):]
        else:
            raise usage_error("unknown option %r" % arg)
    if command is None:
        raise usage_error("no command given")
    low, high, allowed = COMMANDS[command]
    for name in options:
        if name not in allowed:
            raise usage_error("option %s is not valid for %s" % (name, command))
    if not low <= len(positionals) <= high:
        raise usage_error("wrong number of arguments for %s" % command)
    if options.get("--format", "text") not in ("text", "csv", "json"):
        raise usage_error("--format must be text, csv or json")
    if command in RAW_COMMANDS and P.to_date(positionals[0 if command != "fulfil" else 1]) is None:
        raise usage_error("bad date %r" % positionals[0 if command != "fulfil" else 1])
    return command, directory, options, positionals


def read_file(directory, name, required):
    try:
        with open(os.path.join(directory, name), "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise Fail(2, "%s: file not found" % name)
        return ""
    except OSError as error:
        raise Fail(2, "%s: cannot read: %s" % (name, error.strerror or error))
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise Fail(2, "%s: not valid UTF-8" % name)


def parsed(name, function, *args):
    try:
        return function(*args)
    except P.ParseError as error:
        raise Fail(1, "%s: line %d: %s" % (name, error.line, error.reason))


def load_catalog(directory):
    return parsed("catalog.txt", P.parse_catalog, read_file(directory, "catalog.txt", True))


def load_movements(directory, catalog):
    text = read_file(directory, "movements.txt", False)
    return parsed("movements.txt", P.parse_movements, text, catalog), text


def load_orders(directory, catalog):
    return parsed("orders.txt", P.parse_orders, read_file(directory, "orders.txt", False), catalog)


def as_json(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines):
    return "".join(line + "\n" for line in lines)


def find_sku(text, catalog):
    if P.SKU_RE.fullmatch(text) and text.upper() in catalog:
        return text.upper()
    raise Fail(1, "unknown SKU %r" % text)


def find_order(text, orders):
    if P.ORDER_ID_RE.fullmatch(text):
        for order in orders:
            if order.id == text.upper():
                return order
    raise Fail(1, "unknown order %r" % text)


def shipped_so_far(order, movements):
    """SKU -> units shipped by earlier `order SO-n` movements, capped at the quantity ordered."""
    note = "order " + order.id
    sent = {}
    for move in movements:
        if move.note == note and move.quantity < 0:
            sent[move.sku] = sent.get(move.sku, 0) - move.quantity
    return {sku: min(quantity, sent.get(sku, 0)) for sku, quantity in order.lines}


def order_status(order, shipped):
    if all(shipped[sku] >= quantity for sku, quantity in order.lines):
        return "complete"
    return "partial" if any(shipped.values()) else "open"


def available_on(movements, sku, date):
    """Most that can leave on DATE without any later movement taking the stock below zero."""
    balance = 0
    least = None  # lowest balance from DATE's close onwards
    for move in P.counting_order(movements):
        if move.sku != sku:
            continue
        if move.date > date and least is None:
            least = balance
        balance += move.quantity
        if least is not None:
            least = min(least, balance)
    return max(0, balance if least is None else least)


def movement_line(date, sku, quantity, note):
    return "%s %s %+d%s" % (date, sku, quantity, " " + note if note else "")


def append_movements(directory, existing_text, catalog, new_lines):
    """Validate existing + new lines as a whole, then append them in one write."""
    path = os.path.join(directory, "movements.txt")
    chunk = "".join(line + "\n" for line in new_lines)
    try:
        existing = open(path, "rb").read() if os.path.exists(path) else b""
    except OSError as error:
        raise Fail(2, "movements.txt: cannot read: %s" % (error.strerror or error))
    prefix = "\n" if existing and not existing.endswith(b"\n") else ""
    try:
        P.parse_movements(existing_text + prefix + chunk, catalog)
        data = (prefix + chunk).encode("utf-8")
    except P.ParseError as error:
        raise Fail(1, "refused: movements.txt: line %d: %s" % (error.line, error.reason))
    except UnicodeEncodeError:
        raise Fail(1, "refused: argument is not valid UTF-8")
    try:
        with open(path, "ab") as handle:
            handle.write(data)
    except OSError as error:
        raise Fail(2, "movements.txt: cannot write: %s" % (error.strerror or error))


# ---------------------------------------------------------------- commands


def cmd_stock(directory, options, args):
    catalog = load_catalog(directory)
    moves, _ = load_movements(directory, catalog)
    levels = P.stock_levels(catalog, moves)
    rows = []
    for sku in sorted(catalog):
        product = catalog[sku]
        rows.append((sku, product.name, levels[sku], P.stock_status(levels[sku], product.reorder)))
    if options.get("--json"):
        return as_json([{"sku": s, "name": n, "onhand": q, "status": t} for s, n, q, t in rows])
    return lines_out("%s %d %s %s" % (s, q, t, n) for s, n, q, t in rows)


def cmd_low(directory, options, args):
    catalog = load_catalog(directory)
    moves, _ = load_movements(directory, catalog)
    levels = P.stock_levels(catalog, moves)
    rows = []
    for sku in sorted(catalog):
        reorder = catalog[sku].reorder
        if P.stock_status(levels[sku], reorder) != "ok":
            rows.append((sku, levels[sku], reorder, max(1, 2 * reorder - levels[sku])))
    if options.get("--json"):
        return as_json([{"sku": s, "onhand": o, "reorder": r, "buy": b} for s, o, r, b in rows])
    return lines_out("%s %d %d %d" % row for row in rows)


def cmd_history(directory, options, args):
    catalog = load_catalog(directory)
    moves, _ = load_movements(directory, catalog)
    sku = find_sku(args[0], catalog)
    rows = []
    balance = 0
    for move in P.counting_order(moves):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move.date.isoformat(), "%+d" % move.quantity, balance, move.note))
    if options.get("--json"):
        return as_json([{"date": d, "delta": q, "balance": b, "note": n} for d, q, b, n in rows])
    return lines_out("%s %s %d%s" % (d, q, b, " " + n if n else "") for d, q, b, n in rows)


def cmd_move(sign):
    def run(directory, options, args):
        catalog = load_catalog(directory)
        moves, text = load_movements(directory, catalog)
        date, sku_text, quantity = args[0], args[1], args[2]
        note = args[3].strip(P.WS) if len(args) == 4 else ""
        sku = find_sku(sku_text, catalog)
        if not P.UINT_RE.fullmatch(quantity) or P.to_int(quantity) == 0:
            raise Fail(1, "refused: quantity %r is not a whole number of one or more" % quantity)
        if "\n" in note or "\r" in note:
            raise Fail(1, "refused: note may not contain a line break")
        line = movement_line(date, sku, sign * P.to_int(quantity), note)
        append_movements(directory, text, catalog, [line])
        return line + "\n"

    return run


def render_quote(order, quote, prefix):
    out = ["%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for line in quote.lines:
        out.append(
            "%s %d %s %s %s %s" % (line.sku, line.quantity, line.unit, line.gross, line.discount, line.net)
        )
    out += [
        "subtotal %s" % quote.subtotal,
        "order discount %s" % quote.order_discount,
        "tax %s" % quote.tax,
        "total %s" % quote.total,
    ]
    return lines_out(out)


def quote_json(order, quote):
    return as_json(
        {
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": l.sku,
                    "quantity": l.quantity,
                    "unit": str(l.unit),
                    "gross": str(l.gross),
                    "discount": str(l.discount),
                    "net": str(l.net),
                }
                for l in quote.lines
            ],
            "subtotal": str(quote.subtotal),
            "order_discount": str(quote.order_discount),
            "tax": str(quote.tax),
            "total": str(quote.total),
        }
    )


def cmd_quote(directory, options, args):
    catalog = load_catalog(directory)
    order = find_order(args[0], load_orders(directory, catalog))
    quote = price_order(order, catalog)
    if options.get("--json"):
        return quote_json(order, quote)
    return render_quote(order, quote, "")


def shipped_order(order, shipped):
    lines = [(sku, shipped[sku]) for sku, _ in order.lines if shipped[sku] > 0]
    return P.Order(order.id, order.date, order.customer, lines)


def cmd_invoice(directory, options, args):
    catalog = load_catalog(directory)
    moves, _ = load_movements(directory, catalog)
    order = find_order(args[0], load_orders(directory, catalog))
    shipped = shipped_so_far(order, moves)
    if not any(shipped.values()):
        raise Fail(1, "nothing has shipped for %s" % order.id)
    synthetic = shipped_order(order, shipped)
    quote = price_order(synthetic, catalog)
    if options.get("--json"):
        return quote_json(synthetic, quote)
    return render_quote(synthetic, quote, "invoice ")


def cmd_fulfil(directory, options, args):
    catalog = load_catalog(directory)
    moves, text = load_movements(directory, catalog)
    order = find_order(args[0], load_orders(directory, catalog))
    date_text = args[1]
    date = P.to_date(date_text)
    if date < order.date:
        raise Fail(1, "refused: %s is before the order date %s" % (date_text, order.date.isoformat()))
    shipped = shipped_so_far(order, moves)
    out = []
    new_lines = []
    for sku, quantity in order.lines:
        owed = quantity - shipped[sku]
        send = min(owed, available_on(moves, sku, date))
        if send > 0:
            new_lines.append(movement_line(date_text, sku, -send, "order " + order.id))
            shipped[sku] += send
        out.append("%s shipped %d backordered %d" % (sku, send, quantity - shipped[sku]))
    out.append("status " + order_status(order, shipped))
    if new_lines:
        append_movements(directory, text, catalog, new_lines)
    return lines_out(out)


def cmd_report(directory, options, args):
    catalog = load_catalog(directory)
    moves, _ = load_movements(directory, catalog)
    orders = load_orders(directory, catalog)
    rows = []
    for order in sorted(orders, key=lambda o: (o.date, P.to_int(o.id[3:]), o.id)):
        shipped = shipped_so_far(order, moves)
        quoted = price_order(order, catalog).total
        if any(shipped.values()):
            invoiced = price_order(shipped_order(order, shipped), catalog).total
        else:
            invoiced = price_order(P.Order(order.id, order.date, order.customer, []), catalog).total
        rows.append(
            (
                order.id,
                order.date.isoformat(),
                order.customer,
                order_status(order, shipped),
                sum(q for _, q in order.lines),
                sum(shipped.values()),
                str(quoted),
                str(invoiced),
            )
        )
    fmt = options.get("--format", "text")
    if fmt == "text":
        return lines_out("%s %s %s %s %d/%d %s %s" % (r[0], r[1], r[2], r[3], r[5], r[4], r[6], r[7]) for r in rows)
    keys = ("order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced")
    if fmt == "json":
        return as_json([dict(zip(keys, r)) for r in rows])
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(keys)
    writer.writerows(rows)
    return buffer.getvalue()


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_move(1),
    "ship": cmd_move(-1),
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


def silence_stdout():
    """Point fd 1 at /dev/null so the interpreter's shutdown flush cannot fail."""
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), 1)
    except OSError:
        pass


def write_stdout(text):
    data = text.encode("utf-8")
    stream = getattr(sys.stdout, "buffer", None)
    try:
        if stream is not None:
            stream.write(data)
            stream.flush()
        else:
            sys.stdout.write(text)
            sys.stdout.flush()
    except BrokenPipeError:
        silence_stdout()
    except OSError as error:
        silence_stdout()
        raise Fail(2, "cannot write output: %s" % (error.strerror or error))


def main(argv=None):
    if hasattr(sys, "set_int_max_str_digits"):
        sys.set_int_max_str_digits(0)
    try:
        command, directory, options, args = parse_args(sys.argv[1:] if argv is None else argv)
        if not os.path.isdir(directory):
            raise Fail(2, "%s: not a directory" % directory)
        output = HANDLERS[command](directory, options, args)
        write_stdout(output)
    except Fail as failure:
        try:
            sys.stderr.write("stockroom: %s\n" % failure.message)
            sys.stderr.flush()
        except OSError:
            pass
        return failure.code
    return 0
import sys

from .cli import main

sys.exit(main())
